import boto3

def batch_publish(topic_arn, messages):
    sns = boto3.client('sns')
    for message in messages:
        response = sns.publish(TopicArn=topic_arn, Message=message, MessageAttributes={'id': {'DataType': 'String', 'StringValue': message}})
        print(f"Published message: {response['MessageId']}")

if __name__ == '__main__':
    topic_arn = 'arn:aws:sns:us-east-1:123456789012:my-topic'
    messages = ['Message 1', 'Message 2', 'Message 3']
    batch_publish(topic_arn, messages)

